package com.zy.zhangyun;

import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.content.*;import android.net.Uri;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.io.*;import java.net.URLEncoder;

public class ChatActivity extends Activity {
  static final int PICK_AVATAR=8; ApiClient api; LinearLayout messages,chatRoot,chatHeader; ScrollView scroll; EditText input; Spinner spinner; TextView name,relationship; Button conversationMode; ImageView avatar; ExecutorService pool=Executors.newSingleThreadExecutor(); ExecutorService eventPool=Executors.newSingleThreadExecutor(); JSONArray roles=new JSONArray(); int currentId=1; int chosenId=-1; int assistantBubble=Color.rgb(75,58,91),userBubble=Color.rgb(189,113,190); volatile boolean eventsRunning=false; String modelProcessor="检测中"; final Handler statusHandler=new Handler(Looper.getMainLooper()); final Runnable statusPoll=new Runnable(){public void run(){refreshModelRuntime();statusHandler.postDelayed(this,15000);}};
  public void onCreate(Bundle b){super.onCreate(b);chosenId=getIntent().getIntExtra("persona_id",-1);getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);if(android.os.Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(true);setContentView(R.layout.activity_chat);api=new ApiClient(this);chatRoot=findViewById(R.id.chatRoot);chatHeader=findViewById(R.id.chatHeader);messages=findViewById(R.id.messages);scroll=findViewById(R.id.scroll);input=findViewById(R.id.message);spinner=findViewById(R.id.roleSpinner);name=findViewById(R.id.roleName);relationship=findViewById(R.id.relationship);conversationMode=findViewById(R.id.conversationMode);avatar=findViewById(R.id.avatar);avatar.setOnClickListener(v->showAvatarFullScreen());conversationMode.setOnClickListener(v->toggleConversationMode());findViewById(R.id.send).setOnClickListener(v->send());findViewById(R.id.changeAvatar).setOnClickListener(v->pickAvatar());findViewById(R.id.editRole).setOnClickListener(v->editRole());findViewById(R.id.leaveChat).setOnClickListener(v->finish());findViewById(R.id.project).setOnClickListener(v->startActivity(new android.content.Intent(this,ProjectActivity.class)));loadRoles();statusHandler.post(statusPoll);}
  void showAvatarFullScreen(){if(avatar.getDrawable()==null)return;final Dialog preview=new Dialog(this,android.R.style.Theme_Black_NoTitleBar_Fullscreen);ImageView image=new ImageView(this);image.setImageDrawable(avatar.getDrawable());image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setBackgroundColor(Color.BLACK);image.setContentDescription("再次点击退出全屏头像");image.setOnClickListener(v->preview.dismiss());preview.setContentView(image,new android.view.ViewGroup.LayoutParams(-1,-1));preview.show();}
  void add(String s,boolean me){TextView t=new TextView(this);t.setText(s);t.setTextSize(16);t.setTextColor(Color.WHITE);t.setSingleLine(false);t.setMaxLines(Integer.MAX_VALUE);t.setHorizontallyScrolling(false);t.setBreakStrategy(android.text.Layout.BREAK_STRATEGY_HIGH_QUALITY);t.setPadding(22,15,22,15);int maxWidth=(int)(getResources().getDisplayMetrics().widthPixels*.84f);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(maxWidth,-2);p.setMargins(0,7,0,7);p.gravity=me?Gravity.END:Gravity.START;t.setLayoutParams(p);t.setBackgroundColor(me?userBubble:assistantBubble);messages.addView(t);scroll.post(()->{scroll.fullScroll(View.FOCUS_DOWN);scroll.postDelayed(()->scroll.fullScroll(View.FOCUS_DOWN),120);});}
  void loadRoles(){pool.execute(()->{try{roles=new JSONObject(api.get("/api/personas")).getJSONArray("personas");ArrayList<String> names=new ArrayList<>();int initial=0;for(int i=0;i<roles.length();i++){JSONObject role=roles.getJSONObject(i);names.add(role.getString("name"));if(role.getInt("id")==chosenId)initial=i;}final int selected=initial;runOnUiThread(()->{spinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));spinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){try{selectRole(pos);}catch(Exception ignored){}}});spinner.setSelection(selected);try{selectRole(selected);}catch(Exception ignored){}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"角色加载失败",Toast.LENGTH_LONG).show());}});}
  int blend(int color,int numerator,int denominator){return Color.rgb(Color.red(color)*numerator/denominator,Color.green(color)*numerator/denominator,Color.blue(color)*numerator/denominator);}
  void applyTheme(int position){int[] colors={Color.rgb(173,79,119),Color.rgb(91,105,174),Color.rgb(49,135,130),Color.rgb(187,120,55),Color.rgb(94,144,81),Color.rgb(166,73,101),Color.rgb(69,102,169),Color.rgb(155,102,55),Color.rgb(51,128,119),Color.rgb(142,76,145)};int color=colors[Math.max(0,position)%colors.length];chatHeader.setBackgroundColor(color);chatRoot.setBackgroundColor(blend(color,48,100));messages.setBackgroundColor(blend(color,42,100));assistantBubble=blend(color,68,100);userBubble=Color.rgb(Math.min(255,Color.red(color)+48),Math.min(255,Color.green(color)+48),Math.min(255,Color.blue(color)+48));avatar.setBackgroundColor(color);}
  String relationshipText(JSONObject r,int affection,int friendship){return "性别 "+("male".equals(r.optString("gender"))?"男":"女")+" · 情感 "+affection+" · 友谊 "+friendship+" · 模型 "+modelProcessor;}
  void selectRole(int pos)throws Exception{JSONObject r=roles.getJSONObject(pos);currentId=r.getInt("id");applyTheme(pos);String roleName=r.getString("name");name.setText(roleName);relationship.setText(relationshipText(r,r.optInt("affection",35),r.optInt("friendship",50)));conversationMode.setText("time".equals(r.optString("conversation_mode"))?"时间模式":"连续模式");loadAvatar(r.optString("avatar",""),roleName);loadHistory(currentId);}
  void toggleConversationMode(){try{JSONObject role=null;for(int i=0;i<roles.length();i++)if(roles.getJSONObject(i).getInt("id")==currentId)role=roles.getJSONObject(i);if(role==null)return;final JSONObject selected=role;final String next="time".equals(role.optString("conversation_mode"))?"continuous":"time";conversationMode.setEnabled(false);pool.execute(()->{try{api.post("/api/personas/"+currentId+"/mode","mode="+URLEncoder.encode(next,"UTF-8"));selected.put("conversation_mode",next);runOnUiThread(()->{conversationMode.setText("time".equals(next)?"时间模式":"连续模式");conversationMode.setEnabled(true);Toast.makeText(this,"已切换为"+("time".equals(next)?"时间模式":"连续模式"),Toast.LENGTH_SHORT).show();});}catch(Exception e){runOnUiThread(()->{conversationMode.setEnabled(true);Toast.makeText(this,"模式保存失败",Toast.LENGTH_SHORT).show();});}});}catch(Exception ignored){}}
  void loadHistory(final int personaId){messages.removeAllViews();pool.execute(()->{try{JSONArray a=new JSONObject(api.get("/api/history?persona_id="+personaId)).getJSONArray("messages");runOnUiThread(()->{if(personaId!=currentId)return;messages.removeAllViews();for(int i=0;i<a.length();i++)try{JSONObject m=a.getJSONObject(i);add(m.getString("content"),m.getString("role").equals("user"));}catch(Exception ignored){}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"聊天记录同步失败",Toast.LENGTH_SHORT).show());}});}
  @Override protected void onResume(){super.onResume();if(currentId>0&&!roles.isNull(0))loadHistory(currentId);}
  @Override protected void onPause(){eventsRunning=false;api.closeEvents();super.onPause();}
  @Override protected void onDestroy(){eventsRunning=false;statusHandler.removeCallbacks(statusPoll);api.closeEvents();eventPool.shutdownNow();pool.shutdownNow();super.onDestroy();}
  void refreshModelRuntime(){pool.execute(()->{try{String processor=new JSONObject(api.get("/api/model-runtime")).optString("processor","未知");modelProcessor=processor;runOnUiThread(()->{try{for(int i=0;i<roles.length();i++){JSONObject r=roles.getJSONObject(i);if(r.getInt("id")==currentId){relationship.setText(relationshipText(r,r.optInt("affection",35),r.optInt("friendship",50)));break;}}}catch(Exception ignored){}});}catch(Exception ignored){modelProcessor="未知";}});}
  void startEventStream(){if(eventsRunning)return;eventsRunning=true;eventPool.execute(()->{while(eventsRunning){try(BufferedReader reader=api.eventStream()){String line;while(eventsRunning&&(line=reader.readLine())!=null){if(!line.startsWith("data: "))continue;try{JSONObject update=new JSONObject(line.substring(6));int personaId=update.optInt("persona_id",-1);if(personaId>0)runOnUiThread(()->{if(personaId==currentId)loadHistory(personaId);});}catch(Exception ignored){}}}catch(Exception ignored){}if(eventsRunning)try{Thread.sleep(1200);}catch(InterruptedException e){return;}}});}
  Bitmap fallbackAvatar(String who){int size=180;Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);int[] colors={Color.rgb(180,100,158),Color.rgb(92,139,185),Color.rgb(190,125,99),Color.rgb(97,158,142),Color.rgb(154,113,194)};c.drawColor(colors[Math.abs(who.hashCode())%colors.length]);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.WHITE);p.setTextSize(82);p.setTextAlign(Paint.Align.CENTER);Paint.FontMetrics fm=p.getFontMetrics();c.drawText(who.substring(0,1),size/2f,size/2f-(fm.ascent+fm.descent)/2f,p);return b;}
  void loadAvatar(String path,String who){pool.execute(()->{Bitmap image=null;try{if(!path.isEmpty()){java.net.URL u=new java.net.URL(api.base()+path);image=BitmapFactory.decodeStream(u.openStream());}}catch(Exception ignored){}final Bitmap shown=image==null?fallbackAvatar(who):image;runOnUiThread(()->avatar.setImageBitmap(shown));});}
  void pickAvatar(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_AVATAR);}
  void editRole(){try{JSONObject r=null;for(int i=0;i<roles.length();i++)if(roles.getJSONObject(i).getInt("id")==currentId)r=roles.getJSONObject(i);if(r==null)return;final JSONObject role=r;ScrollView holder=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);holder.addView(box);int pad=(int)(20*getResources().getDisplayMetrics().density);box.setPadding(pad,0,pad,0);EditText newName=new EditText(this);newName.setHint("名字");newName.setText(role.getString("name"));Spinner gender=new Spinner(this);ArrayAdapter<String> choices=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,java.util.Arrays.asList("女性","男性"));gender.setAdapter(choices);gender.setSelection("male".equals(role.optString("gender"))?1:0);EditText prompt=new EditText(this);prompt.setHint("角色描述（16行）");prompt.setText(role.optString("prompt"));prompt.setMinLines(16);prompt.setMaxLines(16);EditText affection=new EditText(this);affection.setHint("情感数值（0-100）");affection.setInputType(2);affection.setText(String.valueOf(role.optInt("affection",35)));EditText friendship=new EditText(this);friendship.setHint("友谊数值（0-100）");friendship.setInputType(2);friendship.setText(String.valueOf(role.optInt("friendship",50)));box.addView(newName);box.addView(gender);box.addView(prompt);box.addView(affection);box.addView(friendship);new AlertDialog.Builder(this).setTitle("编辑对象").setView(holder).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->pool.execute(()->{try{String a=affection.getText().toString().trim(),f=friendship.getText().toString().trim(),g=gender.getSelectedItemPosition()==1?"male":"female";if(a.isEmpty())a=String.valueOf(role.optInt("affection",35));if(f.isEmpty())f=String.valueOf(role.optInt("friendship",50));String body="name="+URLEncoder.encode(newName.getText().toString(),"UTF-8")+"&prompt="+URLEncoder.encode(prompt.getText().toString(),"UTF-8")+"&affection="+URLEncoder.encode(a,"UTF-8")+"&friendship="+URLEncoder.encode(f,"UTF-8")+"&gender="+URLEncoder.encode(g,"UTF-8");api.post("/api/personas/"+currentId,body);runOnUiThread(()->{Toast.makeText(this,"已保存",Toast.LENGTH_SHORT).show();loadRoles();});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"保存失败",Toast.LENGTH_SHORT).show());}})).show();}catch(Exception ignored){}}
@Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=PICK_AVATAR||result!=RESULT_OK||data==null)return;pool.execute(()->{try{Uri uri=data.getData();File f=new File(getCacheDir(),"avatar-"+currentId+".jpg");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}JSONObject response=new JSONObject(api.upload(f,"image/jpeg",currentId));String url=response.getString("url");loadAvatar(url,name.getText().toString());runOnUiThread(()->Toast.makeText(this,"头像已更换",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"头像上传失败",Toast.LENGTH_LONG).show());}});}
  void send(){String s=input.getText().toString().trim();if(s.isEmpty())return;final int personaId=currentId;add(s,true);input.setText("");pool.execute(()->{try{JSONObject out=new JSONObject(api.chat(s,personaId));JSONObject rel=out.optJSONObject("relationship");runOnUiThread(()->{if(rel!=null&&personaId==currentId)relationship.setText("情感 "+rel.optInt("affection")+" · 友谊 "+rel.optInt("friendship")+" · 模型 "+modelProcessor);loadHistory(personaId);});}catch(Exception e){runOnUiThread(()->{Toast.makeText(this,"消息发送失败，请稍后重试",Toast.LENGTH_SHORT).show();loadHistory(personaId);});}});}
}
